@bobylito here's an example of how I would use `rootTag`:

```
const Template = 'instantsearch.js/es/components/Template.js';

class HitsTable extends React.Component {
  renderWithResults() {
    const renderedHits = map(this.props.hits, (hit, position) => {
      const data = {
        ...hit,
        __hitIndex: position,
      };
      return (
        <Template
          data={data}
          key={data.objectID}
          rootProps={{ className: this.props.cssClasses.item }}
          rootTag="tr"
          templateKey="item"
          {...this.props.templateProps}
        />
      );
    });

    return <table className={this.props.cssClasses.root}>{renderedHits}</table>;
  }
}
```

There really isn't an alternative - aside from duplicating the `Template` component with my own that allows this, or using a widget that renders a table as divs.
